import React, { useState } from 'react';

function RentalForm({ car, onSubmit, onCancel }) {

    const [customerName, setCustomerName] = useState('');
    const [customerPhone, setCustomerPhone] = useState('');
    const [pickupDate, setPickupDate] = useState('');
    const [returnDate, setReturnDate] = useState('');

    let days = 0;

    if (pickupDate && returnDate) {

        const pickup = new Date(pickupDate);
        const ret = new Date(returnDate);
        const diff = ret - pickup;
        days = Math.max(1, Math.ceil(diff / (1000 * 60 * 60 * 24)));

    }

    const total = days * (car.rentalPricePerDay || 0);

    function handleSubmit(e) {

        e.preventDefault();

        const rentalData = {
            carId: car.id,
            customerName: customerName,
            customerPhone: customerPhone,
            pickupDate: pickupDate,
            returnDate: returnDate,
            rentalDays: days,
            totalCost: total
        };

        onSubmit(rentalData);

    }

    return (

        <div style={{ background: '#fff', borderRadius: '16px', padding: '1.5rem', boxShadow: '0 4px 16px rgba(0,0,0,0.1)', border: '2px solid #059669' }}>

            <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '1rem', paddingBottom: '0.8rem', borderBottom: '3px solid #059669' }}>

                <h2 style={{ margin: 0, fontSize: '1.1rem', color: '#1a1a2e' }}>
                    Rent a Car
                </h2>

            </div>

            <div style={{ background: '#f0fdf4', borderRadius: '10px', padding: '0.8rem 1rem', marginBottom: '1.2rem', display: 'flex', alignItems: 'center', gap: '0.75rem', border: '1px solid #bbf7d0' }}>

                <div>

                    <div style={{ fontWeight: 600, color: '#065f46' }}>
                        {car.carName} - {car.plateNumber}
                    </div>

                    <div style={{ fontSize: '0.85rem', color: '#047857' }}>
                        {car.brand} {car.model} - TSh {car.rentalPricePerDay?.toLocaleString()}/day
                    </div>

                </div>

            </div>

            <form onSubmit={handleSubmit}>

                <div style={{ marginBottom: '0.8rem' }}>

                    <label style={{ color: '#374151', fontSize: '0.85rem', fontWeight: 500, display: 'block', marginBottom: '0.25rem' }}>
                        Customer Name
                    </label>

                    <input type="text"
                        value={customerName}
                        onChange={function(e) { setCustomerName(e.target.value); }}
                        required
                        placeholder="e.g. Juma Mohamed"
                        style={{ width: '100%', padding: '0.6rem 0.8rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', outline: 'none', boxSizing: 'border-box' }} />

                </div>

                <div style={{ marginBottom: '0.8rem' }}>

                    <label style={{ color: '#374151', fontSize: '0.85rem', fontWeight: 500, display: 'block', marginBottom: '0.25rem' }}>
                        Customer Phone
                    </label>

                    <input type="text"
                        value={customerPhone}
                        onChange={function(e) { setCustomerPhone(e.target.value); }}
                        required
                        placeholder="e.g. +255-712-345-678"
                        style={{ width: '100%', padding: '0.6rem 0.8rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', outline: 'none', boxSizing: 'border-box' }} />

                </div>

                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.8rem', marginBottom: '1rem' }}>

                    <div>

                        <label style={{ color: '#374151', fontSize: '0.85rem', fontWeight: 500, display: 'block', marginBottom: '0.25rem' }}>
                            Pickup Date
                        </label>

                        <input type="date"
                            value={pickupDate}
                            onChange={function(e) { setPickupDate(e.target.value); }}
                            required
                            style={{ width: '100%', padding: '0.6rem 0.8rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', outline: 'none', boxSizing: 'border-box' }} />

                    </div>

                    <div>

                        <label style={{ color: '#374151', fontSize: '0.85rem', fontWeight: 500, display: 'block', marginBottom: '0.25rem' }}>
                            Return Date
                        </label>

                        <input type="date"
                            value={returnDate}
                            onChange={function(e) { setReturnDate(e.target.value); }}
                            required
                            style={{ width: '100%', padding: '0.6rem 0.8rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', outline: 'none', boxSizing: 'border-box' }} />

                    </div>

                </div>

                {days > 0 && (

                    <div style={{ background: '#fef3c7', border: '1px solid #fde68a', borderRadius: '10px', padding: '0.8rem 1rem', marginBottom: '1.2rem' }}>

                        <div style={{ display: 'flex', justifyContent: 'space-between', color: '#92400e', fontSize: '0.9rem' }}>

                            <span>
                                Rental Period: <strong>{days} day(s)</strong>
                            </span>

                            <span>
                                TSh {car.rentalPricePerDay?.toLocaleString()} x {days}
                            </span>

                        </div>

                        <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '0.4rem', paddingTop: '0.4rem', borderTop: '1px dashed #fde68a', fontSize: '1.1rem', fontWeight: 700, color: '#1a1a2e' }}>

                            <span>Total Cost</span>
                            <span>TSh {total.toLocaleString()}</span>

                        </div>

                    </div>

                )}

                <div style={{ display: 'flex', gap: '0.75rem' }}>

                    <button type="submit"
                        disabled={days === 0}
                        style={{ flex: 1, padding: '0.7rem', background: days ? '#059669' : '#9ca3af', color: '#fff', border: 'none', borderRadius: '8px', fontWeight: 700, cursor: days ? 'pointer' : 'not-allowed', fontSize: '1rem' }}>
                        Confirm Rental
                    </button>

                    <button type="button" onClick={onCancel}
                        style={{ padding: '0.7rem 1.2rem', background: '#f3f4f6', color: '#374151', border: '1px solid #d1d5db', borderRadius: '8px', fontWeight: 500, cursor: 'pointer' }}>
                        Cancel
                    </button>

                </div>

            </form>

        </div>

    );

}

export default RentalForm;
